#include <mach/mach.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
int main(int argc, char **argv) {
  if (argc != 2) return 1;
  char *end;
  long value = strtol(argv[1], &end, 10);
  if (*end != '\0' || value <= 0) return 1;
  mach_port_t task = MACH_PORT_NULL;
  kern_return_t result = task_for_pid(mach_task_self(), (pid_t)value, &task);
  kern_return_t control = task_for_pid(mach_task_self(), getpid(), &task);
  if (task != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), task);
  printf("{\"targetTaskAccessGranted\":%s,\"targetResult\":%d,\"selfControlResult\":%d}\n",
    result == KERN_SUCCESS ? "true" : "false", result, control);
  return 0;
}
